-- PROPOZYCJA — NIE URUCHAMIAĆ bez decyzji orkiestratora.
-- Reguły bazy wiedzy (portal_wiedza) dla generatora pojedynczych dokumentów kadrowych.
-- Każda reguła została przeczytana w tekście jednolitym aktu (rejestr ELI) w dniu 2026-10-09.
-- Format jak w supabase/migrations/portal_wiedza_seed.sql; kolumna eli = akt pierwotny,
-- który śledzi prawo-monitor.

insert into public.portal_prawo_akty (eli, tytul, skrot) values
  ('DU/1964/93', 'Kodeks cywilny', 'Kodeks cywilny'),
  ('DU/1960/168', 'Kodeks postępowania administracyjnego', 'KPA'),
  ('DU/2006/1635', 'Ustawa o opłacie skarbowej', 'Ustawa o opłacie skarbowej'),
  ('DU/1991/234', 'Ustawa o związkach zawodowych', 'Ustawa o związkach zawodowych'),
  ('DU/2003/844', 'Ustawa o szczególnych zasadach rozwiązywania z pracownikami stosunków pracy z przyczyn niedotyczących pracowników', 'Ustawa o zwolnieniach grupowych'),
  ('DU/2016/2292', 'Rozporządzenie w sprawie świadectwa pracy', 'Rozp. — świadectwo pracy'),
  ('DU/2018/2369', 'Rozporządzenie w sprawie dokumentacji pracowniczej', 'Rozp. — dokumentacja pracownicza'),
  ('DU/1996/332', 'Rozporządzenie w sprawie przeprowadzania badań lekarskich pracowników', 'Rozp. — badania lekarskie'),
  ('DU/2004/1860', 'Rozporządzenie w sprawie szkolenia w dziedzinie bezpieczeństwa i higieny pracy', 'Rozp. — szkolenia BHP'),
  ('DU/2025/322', 'Rozporządzenie w sprawie wniosków dotyczących uprawnień pracowników związanych z rodzicielstwem', 'Rozp. — wnioski rodzicielskie'),
  ('DU/1996/281', 'Rozporządzenie w sprawie sposobu usprawiedliwiania nieobecności w pracy oraz udzielania pracownikom zwolnień od pracy', 'Rozp. — usprawiedliwianie nieobecności'),
  ('DU/2019/1102', 'Rozporządzenie w sprawie deklaracji o rezygnacji z dokonywania wpłat do PPK', 'Rozp. — rezygnacja z PPK')
